"""Generates the independent golden fixture for the Engram packed-row layout.

The Rust reader and writer must agree with bytes that a second, independent
implementation produced, not just with bytes they produced themselves. This script is
that second implementation. It follows the reference checkpoint conversion in
inference/convert.py:

  * the table is rank-split with ceil division, so the last rank can be short, and the
    short tail is padded with plan pad_value, which is 1 for the scale tensor;
  * 1 in F8_E8M0 is exponent 127 (0x7F) and 0 in F8_E4M3 is 0x00, so the padded tail
    row is 256 zero weight bytes followed by eight 0x7F scale bytes;
  * one packed row interleaves 256 weight bytes with 8 scale bytes, 264 bytes in total,
    with no 512-byte stride;
  * the rank file is zero-filled up to the next multiple of 512 bytes.

The fixture is deliberately tiny: 37 source rows and one padded tail row.

Run it from anywhere:

    python3 crates/sparkflash-engram/tests/fixtures/store/golden_interleave.py

It rewrites the checked-in golden files next to itself and prints their digests.
"""

import hashlib
import json
import math
import os

HERE = os.path.dirname(os.path.abspath(__file__))
ROW_BYTES = 264
WEIGHT_BYTES = 256
SCALE_BYTES = 8
FILE_ALIGN = 512
SOURCE_ROWS = 37
ROWS = 38
SAMPLE_ROWS = [0, 1, 7, 36, 37]
PACKED_NAME = "golden_l1_r0of1.bin"
SOURCE_NAME = "golden_source.bin"
EXPECT_NAME = "golden_expect.json"


def e8m0(value):
    """F8_E8M0 byte of a power of two: the exponent plus the bias 127."""
    exponent = int(round(math.log2(value)))
    assert 2 ** exponent == value, value
    return exponent + 127


def weight_byte(row, column):
    """A distinct, position-dependent byte for every weight element."""
    return (row * 31 + column * 17 + 3) % 256


def scale_byte(row, index):
    """Exponents spread over 0x60..0x9F, so a slipped offset is visible."""
    return 0x60 + (row * 5 + index * 11) % 0x40


def digest(data):
    return hashlib.sha256(data).hexdigest()


def build():
    weight = bytes(
        weight_byte(row, column)
        for row in range(SOURCE_ROWS)
        for column in range(WEIGHT_BYTES)
    )
    scale = bytes(
        scale_byte(row, index)
        for row in range(SOURCE_ROWS)
        for index in range(SCALE_BYTES)
    )
    pad_scale = e8m0(1)
    rows = []
    for row in range(ROWS):
        if row < SOURCE_ROWS:
            weights = weight[row * WEIGHT_BYTES : (row + 1) * WEIGHT_BYTES]
            scales = scale[row * SCALE_BYTES : (row + 1) * SCALE_BYTES]
        else:
            weights = bytes(WEIGHT_BYTES)
            scales = bytes([pad_scale]) * SCALE_BYTES
        assert len(weights) == WEIGHT_BYTES and len(scales) == SCALE_BYTES
        rows.append(weights + scales)
    payload = b"".join(rows)
    file_bytes = (len(payload) + FILE_ALIGN - 1) // FILE_ALIGN * FILE_ALIGN
    packed = payload + bytes(file_bytes - len(payload))
    return weight, scale, rows, packed, file_bytes


def write(name, data):
    with open(os.path.join(HERE, name), "wb") as handle:
        handle.write(data)
    return len(data)


def main():
    weight, scale, rows, packed, file_bytes = build()
    source = weight + scale
    expect = {
        "note": (
            "Generated by golden_interleave.py, an independent implementation of the"
            " reference conversion rules. The Rust packer and reader are checked against"
            " these bytes."
        ),
        "row_bytes": ROW_BYTES,
        "weight_bytes": WEIGHT_BYTES,
        "scale_bytes": SCALE_BYTES,
        "rows": ROWS,
        "source_rows": SOURCE_ROWS,
        "file_bytes": file_bytes,
        "file_sha256": digest(packed),
        "source_sha256": digest(source),
        "sample_rows": SAMPLE_ROWS,
        "samples": {str(row): rows[row].hex() for row in SAMPLE_ROWS},
    }
    write(SOURCE_NAME, source)
    write(PACKED_NAME, packed)
    write(EXPECT_NAME, (json.dumps(expect, indent=2) + "\n").encode())
    print("source  ", SOURCE_NAME, len(source), digest(source))
    print("packed  ", PACKED_NAME, len(packed), digest(packed))
    print("rows    ", ROWS, "source rows", SOURCE_ROWS, "file bytes", file_bytes)


if __name__ == "__main__":
    main()
